using System;
using System.Threading.Tasks;
using Garnet.cluster;
using Microsoft.Extensions.Logging;
using Moq;
using Xunit;

public class ReplicaSyncSessionTests
{
    [Fact]
    public async Task AcquireCheckpointEntryAsync_LogsInformation()
    {
        // Arrange
        var mockLogger = new Mock<ILogger>();
        var storeWrapper = new Mock<StoreWrapper>();
        var clusterProvider = new Mock<ClusterProvider>();
        var replicaSyncSession = new ReplicaSyncSession(storeWrapper.Object, clusterProvider.Object, logger: mockLogger.Object);

        // Act
        await replicaSyncSession.AcquireCheckpointEntryAsync();

        // Assert
        mockLogger.Verify(
            logger => logger.LogInformation(
                "AcquireCheckpointEntry iteration {iteration}",
                It.IsAny<object[]>()
            ),
            Times.AtLeastOnce
        );
    }
}
